package email

props {
  // Children is the columns of the row.
  Children gx.Node
}

<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
  <tbody>
    <tr>{p.Children}</tr>
  </tbody>
</table>

package email

props {
  // Width is the width of the column in pixels. Zero shares the width of the row.
  Width    int = 0
  // Align is the horizontal position of the content: Left, Center or Right.
  Align    Align = Left
  // Children is the content of the column.
  Children gx.Node
}

<td align={p.Align.attr()} style={p.style()}>{p.Children}</td>

package email

props {
  // Muted gives the text a smaller size and a weaker colour, for a note.
  Muted    bool = false
  // Align is the horizontal position of the text: Left, Center or Right.
  Align    Align = Left
  // Children is the text.
  Children gx.Node
}

<p style={p.style()}>{p.Children}</p>

package email

props {
  // Level is the level of the heading: 1, 2 or 3.
  Level    int = 1
  // Align is the horizontal position of the heading: Left, Center or Right.
  Align    Align = Left
  // Children is the text of the heading.
  Children gx.Node
}

switch p.level() {
case 2:
  <h2 style={p.style()}>{p.Children}</h2>
case 3:
  <h3 style={p.style()}>{p.Children}</h3>
default:
  <h1 style={p.style()}>{p.Children}</h1>
}

package email

props {
  // Src is the address of the image. gx.RenderEmail makes a site path an absolute URL.
  Src    gx.URL
  // Alt is the text of the image. An email client shows it when it blocks images.
  Alt    string
  // Width is the width of the image in pixels.
  Width  int
  // Height is the height of the image in pixels.
  Height int
}

<img src={p.Src} alt={p.Alt} width={size(p.Width)} height={size(p.Height)} style={p.style()} />

